    (4, N'Bike Frame', N'Road-150', N'en    ', N'Light, stiff frame'),
    (1, N'Bike', N'Road-150', N'fr    ', N'Cadre léger '),
    (4, N'Bike Frame', N'Road-150', N'fr    ', N'Cadre léger '),
